-- Closed-copy liabilities (2026-10-18, approved by Paul: "系統自動收尾"): a reservation left quarantined on a copy that
-- is stopped, proven flat after its order ended, with no money moving and no generation running bounds no exposure, and
-- nothing could release it (strategy 12, mainnet 10:12: its fill was misattributed, so no settlement can ever prove it).
-- The worker's system checks release it with reason 'closed_account', its evidence digest the stop's flat certificate.
-- Widens the check only (one more allowed reason): every existing row validates unchanged.
-- Rollback: restore 0055's check; fails only if a 'closed_account' row exists (re-quarantine those first).
ALTER TABLE "copy_live_risk_reservations" DROP CONSTRAINT "copy_live_risk_reservations_release_check";--> statement-breakpoint
ALTER TABLE "copy_live_risk_reservations" ADD CONSTRAINT "copy_live_risk_reservations_release_check" CHECK (("copy_live_risk_reservations"."state" <> 'released' and "copy_live_risk_reservations"."release_reason" is null and "copy_live_risk_reservations"."release_evidence_digest" is null) or ("copy_live_risk_reservations"."state" = 'released' and "copy_live_risk_reservations"."release_reason" is not null and "copy_live_risk_reservations"."release_evidence_digest" is not null and "copy_live_risk_reservations"."release_evidence_digest" ~ '^[0-9a-f]{64}$' and (("copy_live_risk_reservations"."release_reason" = 'unattempted_expired' and "copy_live_risk_reservations"."attempted_at" is null and "copy_live_risk_reservations"."exchange_order_id" is null) or ("copy_live_risk_reservations"."release_reason" = 'verified_settlement' and "copy_live_risk_reservations"."attempted_at" is not null) or ("copy_live_risk_reservations"."release_reason" = 'expired_unplaced' and "copy_live_risk_reservations"."attempted_at" is not null and "copy_live_risk_reservations"."exchange_order_id" is null) or "copy_live_risk_reservations"."release_reason" = 'closed_account')));